// n8n Code node (JavaScript)

// Número original vindo do Edit Fields
let numeroOriginal =  $('Edit Fields1').first().json.telefone || "999999";

// Limpa tudo que não for dígito
let numeroLimpo = numeroOriginal.replace(/\D/g, "");

// Se tiver 10 ou 11 dígitos, adiciona 55 na frente
if (numeroLimpo.length === 10 || numeroLimpo.length === 11) {
  numeroLimpo = "55" + numeroLimpo;
}

// Monta o número corrigido
const telefoneCorrigido = numeroLimpo;

// Pega os últimos 8 dígitos
const telefoneUltimos8 = telefoneCorrigido.slice(-8);

return [
  {
    json: {
      TelefoneCorrigido: telefoneCorrigido,
      TelefoneUltimos8: telefoneUltimos8
    }
  }
];

// n8n Code node (JavaScript)

// ---- helpers ----
function safeParse(v) {
  if (v == null) return null;
  if (typeof v === 'object') return v;
  try { return JSON.parse(String(v)); } catch { return null; }
}

function getFirstByField(cf = [], wanted = []) {
  if (!Array.isArray(cf)) return null;
  const f = cf.find(x =>
    wanted.includes(x.field_code) ||
    wanted.includes(x.field_name)
  );
  return f?.values?.[0]?.value ?? null;
}

function getFirstPhone(cf = []) {
  return getFirstByField(cf, ['PHONE', 'Phone']);
}

function getFirstEmail(cf = []) {
  return getFirstByField(cf, ['EMAIL', 'Email', 'E-mail']);
}

function scoreContact(c) {
  if (!c || typeof c !== 'object') return -1;
  let s = 0;
  if (c.name) s += 2;
  if (getFirstPhone(c.custom_fields_values)) s += 2;
  s += Array.isArray(c.custom_fields_values) ? c.custom_fields_values.length : 0;
  s += Array.isArray(c._embedded?.tags) ? c._embedded.tags.length : 0;
  s += Array.isArray(c._embedded?.companies) ? c._embedded.companies.length : 0;
  if (c.first_name) s += 1;
  if (c.last_name) s += 1;
  if (c.responsible_user_id) s += 1;
  return s;
}

// ---- main ----
const out = [];

for (const item of $input.all()) {
  const data = safeParse(item.json?.data) || safeParse(item.json) || item.json;
  if (!data || typeof data !== 'object') continue;

  const contacts = data._embedded?.contacts ?? [];
  const leadRows = [];

  for (const contact of contacts) {
    const leads = contact._embedded?.leads ?? [];
    for (const ld of leads) {
      leadRows.push({
        json: {
          contact_id: contact.id ?? null,
          contact_name: contact.name ?? null,
          phone: getFirstPhone(contact.custom_fields_values) ?? null,
          email: getFirstEmail(contact.custom_fields_values) ?? null, // sempre presente
          contact_link: contact._links?.self?.href ?? null,
          lead_id: ld?.id ?? null,
          lead_link: ld?._links?.self?.href ?? null,
        }
      });
    }
  }

  if (leadRows.length > 0) {
    out.push(...leadRows);
  } else {
    if (contacts.length > 0) {
      let best = contacts[0];
      let bestScore = scoreContact(best);
      for (let i = 1; i < contacts.length; i++) {
        const sc = scoreContact(contacts[i]);
        if (sc > bestScore) {
          best = contacts[i];
          bestScore = sc;
        }
      }
      out.push({
        json: {
          contact_id: best.id ?? null,
          contact_name: best.name ?? null,
          phone: getFirstPhone(best.custom_fields_values) ?? null,
          email: getFirstEmail(best.custom_fields_values) ?? null, // sempre presente
          contact_link: best._links?.self?.href ?? null,
          lead_id: null,
          lead_link: null,
          _note: "Sem leads; retornado contato mais completo"
        }
      });
    }
  }
}

return out;

// n8n Code node (JavaScript)

// =========================
// CAMPOS DO NODE NO TOPO
// =========================
const PIPELINE_VENDAS = String($("Edit Fields12").first().json.pipeline_vendas ?? "");
const ETAPA_GANHO_PIPELINE_VENDAS = String($("Edit Fields12").first().json.etapa_ganho_pipeline_vendas_etapa_pipe ?? "");

// =========================
// FUNCOES AUXILIARES
// =========================
function parseMaybeJson(v) {
  if (v == null) return null;
  if (typeof v === "object") return v;
  try {
    return JSON.parse(String(v));
  } catch {
    return null;
  }
}

function escapeJsonString(s) {
  return String(s)
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"');
}

function extractTags(lead) {
  const arr = lead?._embedded?.tags;

  if (!Array.isArray(arr)) {
    return {
      tags_raw: [],
      tag_ids: [],
      tag_names: [],
      tag_names_csv: "",
      tags_string: "",
    };
  }

  const names = arr
    .filter(t => t && (t.name != null || t.id != null))
    .map(t => String(t.name ?? "").trim())
    .filter(name => name.length > 0);

  const seen = new Set();
  const tag_names = names.filter(name => {
    const key = name.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  const tags_raw = tag_names.map(name => ({ name }));
  const tag_ids = arr.map(t => t?.id).filter(v => v != null);

  let tags_string = "";
  if (tag_names.length) {
    const parts = tag_names.map(n => `{ "name": "${escapeJsonString(n)}" }`);
    tags_string = parts.join(",") + ",";
  }

  return {
    tags_raw,
    tag_ids,
    tag_names,
    tag_names_csv: tag_names.join(", "),
    tags_string,
  };
}

function buildCreateDealResponse(reason) {
  return [{
    json: {
      found: false,
      should_create_deal: true,
      create_deal_reason: reason,
      id: null,
      name: null,
      pipeline_id: null,
      status_id: null,
      updated_at_unix: null,
      link_self: null,
      tags_raw: [],
      tag_ids: [],
      tag_names: [],
      tag_names_csv: "",
      tags_string: "",
      pipeline_vendas: PIPELINE_VENDAS,
      etapa_ganho_pipeline_vendas_etapa_pipe: ETAPA_GANHO_PIPELINE_VENDAS,
    }
  }];
}

// =========================
// ENTRADA
// =========================
const all = $input.all()
  .map(it => parseMaybeJson(it.json?.data) || it.json)
  .filter(o => o && typeof o === "object");

// =========================
// FILTRO BASE
// =========================
// Mantive:
// - id válido
// - não deletado
// - não perdido
const eligible = all.filter(l =>
  l &&
  l.id != null &&
  !l.is_deleted &&
  l.loss_reason_id == null
);

// =========================
// FILTRA SOMENTE O PIPELINE DE VENDAS
// =========================
const dealsNoPipeline = eligible.filter(l =>
  String(l.pipeline_id ?? "") === PIPELINE_VENDAS
);

// Se não existe nenhum deal no pipeline, criar deal
if (!dealsNoPipeline.length) {
  return buildCreateDealResponse("nenhum_deal_no_pipeline");
}

// Ordena por updated_at desc para escolher o mais recente
dealsNoPipeline.sort((a, b) => (Number(b.updated_at) || 0) - (Number(a.updated_at) || 0));

// Procura algum deal no pipeline que NAO esteja na etapa de ganho
const dealForaDaEtapaGanho = dealsNoPipeline.find(l =>
  String(l.status_id ?? "") !== ETAPA_GANHO_PIPELINE_VENDAS
);

// Se encontrou deal no pipeline e ele NÃO está na etapa de ganho, retorna ele
if (dealForaDaEtapaGanho) {
  const tagsInfo = extractTags(dealForaDaEtapaGanho);

  return [{
    json: {
      found: true,
      should_create_deal: false,
      create_deal_reason: null,
      id: dealForaDaEtapaGanho.id,
      name: dealForaDaEtapaGanho.name ?? null,
      pipeline_id: dealForaDaEtapaGanho.pipeline_id ?? null,
      status_id: dealForaDaEtapaGanho.status_id ?? null,
      updated_at_unix: Number(dealForaDaEtapaGanho.updated_at) || null,
      link_self: dealForaDaEtapaGanho._links?.self?.href ?? null,
      ...tagsInfo,
      pipeline_vendas: PIPELINE_VENDAS,
      etapa_ganho_pipeline_vendas_etapa_pipe: ETAPA_GANHO_PIPELINE_VENDAS,
    }
  }];
}

// Se todos os deals encontrados no pipeline estiverem na etapa de ganho, criar deal
return buildCreateDealResponse("deal_existente_apenas_em_etapa_ganho");

