// Verifica se os dados estão em formato de string JSON e converte para objeto
if (typeof inputData.data === "string") {
    inputData = JSON.parse(inputData.data);
}

// Verifica a estrutura do JSON
if (!inputData || !inputData._embedded || !inputData._embedded.statuses) {
    throw new Error("Estrutura do JSON inválida ou sem statuses.");
}

// Criar um objeto para armazenar os statuses
let statusMap = {};

// Percorre os statuses e armazena no objeto
inputData._embedded.statuses.forEach(status => {
    statusMap[status.name] = status.id;
});

// Retorna o objeto contendo os nomes como chaves e os IDs como valores
return [{ statuses: statusMap }];

